@lru_cache(maxsize=1000)
def _infer_flatpak_license(self, app_id: str) -> List[str]:
    """Infer license based on Flatpak app ID patterns (cached)."""
    # Check for known proprietary patterns first
    for pattern, licenses in self._proprietary_patterns.items():
        if app_id.startswith(pattern):
            return licenses

    # Check for known FOSS patterns
    for pattern, licenses in self._foss_patterns.items():
        if app_id.startswith(pattern):
            return licenses

    # Default to unknown for unrecognized patterns
    return ["unknown"]
